// The profile import bundle: the Electron profile importer's plan builder
// (shims/profile-import.js) for the sandboxed runner. It carries no shipping
// module, no prelude and no host call: its one entry takes the stores' text
// and returns the plan.
//   node chromium/tools/build-profile-import-bundle.mjs [--check]
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const runner = path.join(root, 'chromium/blanc/services/sync_runner');
export function profileImportBundle() {
  const shim = fs.readFileSync(path.join(runner, 'shims/profile-import.js'), 'utf8');
  return `// Generated by chromium/tools/build-profile-import-bundle.mjs. Don't edit.
(function(g){const module={exports:{}};(function(module,exports){
${shim}
})(module,module.exports);const plan=module.exports;
g.__call=(method,argsJson,done)=>{try{if(method!=='profile.plan')throw Error('forbidden');
const args=JSON.parse(argsJson);done(true,JSON.stringify(plan(Array.isArray(args)?args[0]:undefined)));
}catch(error){done(false,String(error&&error.message||error));}};})(globalThis);
`;
}
export const hashProfileImport = text => crypto.createHash('sha256').update(text).digest('hex');
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = profileImportBundle(), hash = hashProfileImport(text);
  const files = {
    'generated/profile-import-bundle.js': text,
    'profile_import_bundle_hash.h': `// Generated by chromium/tools/build-profile-import-bundle.mjs. Don't edit.
#ifndef BLANC_SERVICES_SYNC_RUNNER_PROFILE_IMPORT_BUNDLE_HASH_H_
#define BLANC_SERVICES_SYNC_RUNNER_PROFILE_IMPORT_BUNDLE_HASH_H_
namespace blanc {
inline constexpr char kBlancProfileImportBundleSha256[] = "${hash}";
}
#endif  // BLANC_SERVICES_SYNC_RUNNER_PROFILE_IMPORT_BUNDLE_HASH_H_
`,
  };
  for (const [name, bytes] of Object.entries(files)) {
    const file = path.join(runner, name);
    if (process.argv.includes('--check')) {
      if (fs.readFileSync(file, 'utf8') !== bytes) throw Error('Profile import bundle is stale: ' + name);
    } else fs.writeFileSync(file, bytes);
  }
  console.log(`profile import ${text.length} bytes, ${hash}`);
}
